/**
 * The set of base eval helper functions exported by the eval test helpers.
 * A call whose callee (directly, via an import alias, or via a local wrapper
 * function) resolves to one of these is considered an eval test declaration.
 */
export const BASE_EVAL_HELPERS = [
  'evalTest',
  'appEvalTest',
  'componentEvalTest',
] as const;

export type BaseEvalHelper = (typeof BASE_EVAL_HELPERS)[number];

const BASE_HELPER_SET: ReadonlySet<string> = new Set(BASE_EVAL_HELPERS);

/**
 * Structured metadata extracted for a single eval test case.
 */
export interface EvalCaseInfo {
  /** The eval policy string, e.g. 'ALWAYS_PASSES'. */
  policy: string;
  /** The `name` of the eval case. */
  name: string;
  /** The `suiteName` of the eval case. */
  suiteName: string;
  /** The `suiteType` of the eval case. */
  suiteType: string;
  /** The `timeout` of the eval case, if statically known. */
  timeout?: number;
  /** Whether the eval case object declares a `files` property. */
  hasFiles: boolean;
  /** Whether the eval case object declares a `prompt` property. */
  hasPrompt: boolean;
  /** The identifier used at the call site (alias or wrapper name). */
  helperName: string;
  /** The base eval helper this call ultimately resolves to. */
  baseHelperName: string;
}

/**
 * The result of statically analyzing an eval source file.
 */
export interface AnalysisResult {
  /** The file path relative to the repo root, always using forward slashes. */
  relativePath: string;
  /** The eval cases discovered in the file. */
  cases: EvalCaseInfo[];
  /**
   * A map of wrapper/alias names to the base eval helper they resolve to.
   * Includes import aliases and local wrapper functions, but not direct
   * (unaliased) imports of the base helpers themselves.
   */
  helpers: Record<string, string>;
  /** Messages describing calls that could not be statically analyzed. */
  diagnostics: string[];
}

export interface AnalyzeEvalSourceOptions {
  /** The path of the file being analyzed. May be absolute or relative. */
  filePath: string;
  /** The repo root used to compute {@link AnalysisResult.relativePath}. */
  repoRoot?: string;
}

/**
