  const { filePath, repoRoot } = options;

  const relativePath = computeRelativePath(filePath, repoRoot);
  const cases: EvalCaseInfo[] = [];
  const helpers: Record<string, string> = {};
  const diagnostics: string[] = [];

  const sourceFile = ts.createSourceFile(
