      const importedName = (element.propertyName ?? element.name).text;
      const localName = element.name.text;
      // Only aliases (local name differs from the imported base helper) are
      // recorded; a direct import of a base helper is the helper itself.
      if (BASE_HELPER_SET.has(importedName) && localName !== importedName) {
        helpers[localName] = importedName;
