    if (!ts.isIdentifier(call.expression)) {
      continue;
    }
    const enclosing = getEnclosingFunctionName(call);
    if (!enclosing) {
      continue;
    }
    let callees = functionCallees.get(enclosing);
    if (!callees) {
      callees = new Set();
      functionCallees.set(enclosing, callees);
    }
    callees.add(call.expression.text);
