    cases.push({
      policy,
      name: fields.name,
      suiteName: fields.suiteName,
      suiteType: fields.suiteType,
      timeout: fields.timeout,
      hasFiles: fields.hasFiles,
      hasPrompt: fields.hasPrompt,
      helperName,
      baseHelperName,
    });
  }

  return { relativePath, cases, helpers, diagnostics };
}

